I’m using the exact state recurrence: each state branches equally among the three piston choices, and recursion stops for a chosen ball when it is either piston-ejected or discarded. Extra balls beyond 100 are treated as harmless continuation balls so end-of-ramp effects cannot distort the comparison.
```python
from functools import lru_cache

def win_probability(target):
    @lru_cache(None)
    def f(platform, nxt):
        if target not in platform:
            if platform and max(platform) < target and nxt <= target:
                pass
        total = 0.0
        # piston 1
        ejected = platform[0]
        if ejected == target:
            a = 1.0
        else:
            new_platform = (platform[1], platform[2], nxt)
            a = f(new_platform, nxt + 1)
        total += a
        # piston 2
        if platform[1] == target:
            b = 1.0
        elif platform[0] == target:
            b = 0.0
        else:
            b = f((platform[2], nxt, nxt + 1), nxt + 2)
        total += b
        # piston 3
        if platform[2] == target:
            c = 1.0
        elif platform[0] == target:
            c = 0.0
        else:
            c = f((platform[1], nxt, nxt + 1), nxt + 2)
        total += c
        return total / 3.0
    return f((1, 2, 3), 4)

probabilities = [(n, win_probability(n)) for n in range(1, 101)]
best_ball, best_probability = max(probabilities, key=lambda x: x[1])
top_five = sorted(probabilities, key=lambda x: x[1], reverse=True)[:5]
print({"best_ball": best_ball, "best_probability": best_probability, "top_five": top_five})
```
