def p(t):
    m = {}
    def q(s, n):
        k = (s, n)
        if k in m:
            return m[k]
        x = 1.0 if s[0] == t else q((s[1], s[2], n), n + 1)
        if s[1] == t:
            y = 1.0
        elif s[0] == t:
            y = 0.0
        else:
            y = q((s[2], n, n + 1), n + 2)
        if s[2] == t:
            z = 1.0
        elif s[0] == t:
            z = 0.0
        else:
            z = q((s[1], n, n + 1), n + 2)
        m[k] = (x + y + z) / 3.0
        return m[k]
    return q((1, 2, 3), 4)

